changeSet.sql:
DROP INDEX IF EXISTS idx_tenant_user_fk;
DROP INDEX IF EXISTS idx_tenant_email_lookup;
CREATE UNIQUE INDEX uq_tenant_project_user ON tenants (project_id, user_id) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX uq_tenant_project_email ON tenants (project_id, email) WHERE email IS NOT NULL;

changeSet.rollback:
DROP INDEX IF EXISTS uq_tenant_project_user;
DROP INDEX IF EXISTS uq_tenant_project_email;
CREATE INDEX idx_tenant_user_fk ON tenants (user_id);
CREATE INDEX idx_tenant_email_lookup ON tenants (email);
